-- Round 4: a messy set of accounts left behind by "the previous admin".
-- DO NOT EDIT THIS FILE. The grader always uses the instructor's copy.
-- bootstrap.sh runs it as root, after schema.sql and load.sql, and then runs your fixes.sql.
-- It starts by dropping these accounts, so it is safe to run again and again.

DROP USER IF EXISTS
  's6705142003_webapp'@'%', 's6705142003_webapp'@'localhost',
  's6705142003_kiosk'@'localhost', 's6705142003_kiosk'@'%',
  's6705142003_intern'@'%', 's6705142003_intern'@'localhost',
  's6705142003_etl'@'localhost', 's6705142003_etl'@'%',
  's6705142003_report'@'localhost', 's6705142003_report'@'%';

CREATE USER 's6705142003_webapp'@'%' IDENTIFIED BY 'Webapp#2026';
GRANT ALL PRIVILEGES ON *.* TO 's6705142003_webapp'@'%' WITH GRANT OPTION;

CREATE USER 's6705142003_kiosk'@'localhost' IDENTIFIED BY '';
GRANT SELECT ON reg_6705142003.students TO 's6705142003_kiosk'@'localhost';

CREATE USER 's6705142003_intern'@'%' IDENTIFIED BY 'Intern#2025';
GRANT SELECT, INSERT, UPDATE ON reg_6705142003.* TO 's6705142003_intern'@'%';

CREATE USER 's6705142003_etl'@'localhost' IDENTIFIED BY 'Etl#2026';
GRANT FILE ON *.* TO 's6705142003_etl'@'localhost';
GRANT INSERT ON reg_6705142003.enrollments TO 's6705142003_etl'@'localhost';

CREATE USER 's6705142003_report'@'localhost' IDENTIFIED BY 'Report#2026';
GRANT SELECT, INSERT, UPDATE, DELETE ON reg_6705142003.* TO 's6705142003_report'@'localhost';
